export const EntryUpdate = {
  "description": "Full replacement of the mutable state; an absent optional field is cleared (the edit form holds the whole entry). media_type and custom-ness are immutable. product_id accepts one narrow change - re-matching an auto-priced entry off an unmatched game product onto a product of the same game and platform (see the field description); anything else answers 400 code invalid_product_change. That re-match stamps match_provenance=user; automated region repoints only ever run on match_provenance=auto entries. On custom entries display_name is required and platform_name/first_release_date replace like any optional field; on product-backed entries all three are rejected. tag_ids replaces the tag set; absent means no tags. custom_value_cents is required when pricing_mode is custom.\n",
  "properties": {
    "box_condition": {
      "$ref": "#/components/schemas/ItemCondition",
    },
    "cover_url": {
      "description": "Custom entries only; an https cover image URL (validated by shape, never fetched).",
      "maxLength": 512,
      "pattern": "^https://",
      "type": "string",
    },
    "currency": {
      "default": "USD",
      "pattern": "^[A-Z]{3}$",
      "type": "string",
    },
    "custom_value_cents": {
      "format": "int64",
      "maximum": 1000000000,
      "minimum": 0,
      "type": "integer",
    },
    "custom_value_entered_cents": {
      "format": "int64",
      "maximum": 1000000000,
      "minimum": 0,
      "type": "integer",
    },
    "custom_value_entered_currency": {
      "pattern": "^[A-Z]{3}$",
      "type": "string",
    },
    "developers": {
      "description": "Custom entries only; developer company names, one per element (full replacement).",
      "items": {
        "maxLength": 120,
        "type": "string",
      },
      "maxItems": 10,
      "type": "array",
    },
    "display_name": {
      "description": "Custom entries only (required there).",
      "maxLength": 200,
      "type": "string",
    },
    "edition": {
      "description": "Per-copy variant note; the idiom for variants of cataloged items.",
      "maxLength": 200,
      "type": "string",
    },
    "first_release_date": {
      "description": "Custom entries only.",
      "format": "date",
      "type": "string",
    },
    "has_box": {
      "default": false,
      "type": "boolean",
    },
    "has_manual": {
      "default": false,
      "type": "boolean",
    },
    "item_condition": {
      "$ref": "#/components/schemas/ItemCondition",
    },
    "manual_condition": {
      "$ref": "#/components/schemas/ItemCondition",
    },
    "notes": {
      "maxLength": 10000,
      "type": "string",
    },
    "packaging": {
      "$ref": "#/components/schemas/Packaging",
    },
    "pinned": {
      "type": "boolean",
    },
    "platform_igdb_id": {
      "description": "Custom entries only; the canonical platform id from the picker.",
      "format": "int64",
      "type": "integer",
    },
    "platform_name": {
      "description": "Custom entries only.",
      "maxLength": 100,
      "type": "string",
    },
    "price_paid_cents": {
      "format": "int64",
      "minimum": 0,
      "type": "integer",
    },
    "pricing_mode": {
      "$ref": "#/components/schemas/PricingMode",
    },
    "pricing_product_id": {
      "format": "uuid",
      "type": "string",
    },
    "product_id": {
      "description": "Narrow re-match. Accepted only when the entry is product-backed with pricing_mode auto, its current product is a game with no price mapping, and the new product is a game of the same family (same igdb game and platform); the same id as the entry already has is a no-op. Anything else answers 400 code invalid_product_change; enrichment unreachable answers 502 code enrichment_unavailable and leaves the entry unchanged. Snapshotted display fields stay as they are.\n",
      "format": "uuid",
      "type": "string",
    },
    "publishers": {
      "description": "Custom entries only; publisher company names, one per element (full replacement).",
      "items": {
        "maxLength": 120,
        "type": "string",
      },
      "maxItems": 10,
      "type": "array",
    },
    "purchased_at": {
      "format": "date",
      "type": "string",
    },
    "purchased_from": {
      "maxLength": 200,
      "type": "string",
    },
    "rating": {
      "maximum": 10,
      "minimum": 1,
      "type": "integer",
    },
    "region": {
      "description": "Entry region. Known values ntsc_u, ntsc_j, pal, region_free, korea, brazil and china are first-class: labeled in the UI, filterable, normalize-lever promotion targets, with release-date chains, availability rows, and localized display snapshots per region (ntsc_u and region_free render the canonical presentation by design). korea, brazil and china have no PriceCharting axis, so they price from base listings as their deliberate proxy. Any other non-empty string is stored verbatim as a display fact and prices like ntsc_u until the value graduates to the known set. On an auto-provenance game entry, a region change repoints the entry to the sibling catalog product whose listing prices that region; snapshotted display fields re-derive from it.",
      "maxLength": 32,
      "type": "string",
    },
    "status": {
      "$ref": "#/components/schemas/EntryStatus",
    },
    "storage_location": {
      "maxLength": 200,
      "type": "string",
    },
    "tag_ids": {
      "items": {
        "format": "uuid",
        "type": "string",
      },
      "maxItems": 50,
      "type": "array",
    },
  },
  "required": ["region", "packaging", "pricing_mode", "status", "pinned"],
  "type": "object",
} as const;

