export const ResolveRequest = {
  "description": "type game requires igdb_game_id + platform_igdb_id (the platform must be one the game released on and not a digital-only platform). Game identity is listing-keyed - (game, platform, PriceCharting listing) - so edition/variant on a game resolve are ignored (entry-level facts, like pc_listing); region is a matching input only (see the region property) and never joins identity. Without pc_product_id the resolve auto-matches by the game name (region-steered) through the shared listing-search cache and lands on the winning listing's product; below the confidence threshold, or with the provider down, it lands on the game+platform's single unmatched product instead - never guessed. Optional match_hint (game only, ignored elsewhere) reweights the scoring toward variant text without changing the search query; a hint nothing matches makes the resolve conservative (unmatched). With pc_product_id (a manual match: the exact listing the user chose) auto-match is skipped and the resolve finds or mints the product carrying that listing (match_confidence 1.0, verified false); unknown id answers 404 unknown_pc_product, provider failure 502 upstream_unavailable. Resolves never touch an existing product's mapping; corrections stay on the admin mapping endpoint. console/accessory require pc_product_id; region/edition/variant distinguish physical variants and are part of hardware identity. type pc_listing requires pc_product_id and mints a price-anchor product for that exact listing; region/edition/variant are ignored (the listing IS the exact variant).\n",
  "properties": {
    "edition": {
      "maxLength": 128,
      "type": "string",
    },
    "igdb_game_id": {
      "format": "int64",
      "type": "integer",
    },
    "match_hint": {
      "maxLength": 128,
      "type": "string",
    },
    "pc_product_id": {
      "format": "int64",
      "type": "integer",
    },
    "platform_igdb_id": {
      "format": "int64",
      "type": "integer",
    },
    "region": {
      "description": "For console/accessory: part of hardware identity, distinguishing physical variants. For game: a matching input only - the entry region (ntsc_u, ntsc_j, pal, region_free, korea, brazil, china) steers which PriceCharting listing auto-match lands on (JP and PAL listings live under region-prefixed or JP-named console axes; korea, brazil and china have no provider axis and match like ntsc_u) and is never stored on the product; ignored when pc_product_id is present; unknown values behave like ntsc_u. Ignored for pc_listing.",
      "maxLength": 32,
      "type": "string",
    },
    "type": {
      "$ref": "#/components/schemas/ProductType",
    },
    "variant": {
      "maxLength": 128,
      "type": "string",
    },
  },
  "required": ["type"],
  "type": "object",
} as const;

